import React, { useState, useEffect } from 'react';
import { getUserRoles } from '../../keycloak';
import './ScheduledEvents.css';

const ScheduledEvents = () => {
    const [expandedEvent, setExpandedEvent] = useState(null);
    const [events, setEvents] = useState([]);
    const [newEvent, setNewEvent] = useState({ title: '', date: '', time: '', description: '' });
    const [showAddForm, setShowAddForm] = useState(false);
    const [userRoles, setUserRoles] = useState([]);

    useEffect(() => {
        const savedEvents = localStorage.getItem('scheduledEvents');
        if (savedEvents) {
            setEvents(JSON.parse(savedEvents));
        } else {
            const initialEvents = [
                { id: 1, title: "Событие 1", date: "15 марта 2025", description: "Открытие весеннего сезона.", time: "15:00", participants: 24 },
                { id: 2, title: "Событие 2", date: "16 марта 2025", description: "Практикум по дыхательным техникам.", time: "11:00", participants: 18 },
                { id: 3, title: "Событие 3", date: "17 марта 2025", description: "Лекция о силе духа.", time: "18:30", participants: 32 }
            ];
            setEvents(initialEvents);
            localStorage.setItem('scheduledEvents', JSON.stringify(initialEvents));
        }

        const roles = getUserRoles();
        setUserRoles(roles);
    }, []);

    const isAdmin = userRoles.includes('admin');

    const toggleExpand = (id) => {
        setExpandedEvent(expandedEvent === id ? null : id);
    };

    const handleAddEvent = () => {
        if (!newEvent.title || !newEvent.date) {
            alert('Заполните название и дату события');
            return;
        }

        const event = {
            id: Date.now(),
            ...newEvent,
            participants: 0
        };

        const updatedEvents = [...events, event];
        setEvents(updatedEvents);
        localStorage.setItem('scheduledEvents', JSON.stringify(updatedEvents));

        setNewEvent({ title: '', date: '', time: '', description: '' });
        setShowAddForm(false);
    };

    const handleDeleteEvent = (id) => {
        if (window.confirm('Удалить событие?')) {
            const updatedEvents = events.filter(event => event.id !== id);
            setEvents(updatedEvents);
            localStorage.setItem('scheduledEvents', JSON.stringify(updatedEvents));
        }
    };

    if (!isAdmin) {
        return (
            <div className="scheduled-events">
                <div className="events-header">
                    <h2>📅 События</h2>
                    <p>Доступно только для администраторов</p>
                </div>
                <div className="access-denied">
                    <span>🔒</span>
                    <p>У вас нет прав для просмотра этой страницы</p>
                </div>
            </div>
        );
    }

    return (
        <div className="scheduled-events">
            <div className="events-header">
                <h2>📅 Управление событиями</h2>
                <p>Добавляйте и управляйте событиями</p>
            </div>

            <div className="admin-controls-events">
                <button
                    className="add-event-button"
                    onClick={() => setShowAddForm(!showAddForm)}
                >
                    {showAddForm ? '✖ Отмена' : '+ Добавить событие'}
                </button>
            </div>

            {showAddForm && (
                <div className="add-event-form">
                    <h3>Новое событие</h3>
                    <input
                        type="text"
                        placeholder="Название события"
                        value={newEvent.title}
                        onChange={(e) => setNewEvent({...newEvent, title: e.target.value})}
                    />
                    <input
                        type="text"
                        placeholder="Дата (например: 25 марта 2025)"
                        value={newEvent.date}
                        onChange={(e) => setNewEvent({...newEvent, date: e.target.value})}
                    />
                    <input
                        type="text"
                        placeholder="Время (например: 15:00)"
                        value={newEvent.time}
                        onChange={(e) => setNewEvent({...newEvent, time: e.target.value})}
                    />
                    <textarea
                        placeholder="Описание"
                        value={newEvent.description}
                        onChange={(e) => setNewEvent({...newEvent, description: e.target.value})}
                        rows="3"
                    />
                    <button onClick={handleAddEvent}>Создать событие</button>
                </div>
            )}

            <div className="events-list">
                {events.map((event) => (
                    <div key={event.id} className={`event-card ${expandedEvent === event.id ? 'expanded' : ''}`}>
                        <div className="event-header" onClick={() => toggleExpand(event.id)}>
                            <div className="event-title-section">
                                <h3 className="event-title">{event.title}</h3>
                                <span className="event-date">{event.date}</span>
                            </div>
                            <div className="event-actions">
                                <button
                                    className="delete-event-btn"
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        handleDeleteEvent(event.id);
                                    }}
                                >
                                    🗑️
                                </button>
                                <div className="event-expand-icon">
                                    {expandedEvent === event.id ? '▲' : '▼'}
                                </div>
                            </div>
                        </div>

                        <div className="event-content">
                            <div className="event-details">
                                <div className="event-detail-item">
                                    <span className="detail-label">⏰ Время:</span>
                                    <span className="detail-value">{event.time}</span>
                                </div>
                            </div>
                            <p className="event-description">{event.description}</p>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

export default ScheduledEvents;
